91	static char *
92	read_infile(char *fname)
93	{
94		register int i, fd, cc;
95		register char *cp;
96		struct stat buf;
97	
98		fd = open(fname, O_RDONLY|O_BINARY);
99		if (fd < 0)
100			error("can't open %s: %s", fname, pcap_strerror(errno));
101	
102		if (fstat(fd, &buf) < 0)
103			error("can't stat %s: %s", fname, pcap_strerror(errno));
104	
105		/*
106		 * _read(), on Windows, has an unsigned int byte count and an
107		 * int return value, so we can't handle a file bigger than
108		 * INT_MAX - 1 bytes (and have no reason to do so; a filter *that*
109		 * big will take forever to compile).  (The -1 is for the '\0' at
110		 * the end of the string.)
111		 */
112		if (buf.st_size > INT_MAX - 1)
113			error("%s is larger than %d bytes; that's too large", fname,
114			    INT_MAX - 1);
115		cp = malloc((u_int)buf.st_size + 1);
116		if (cp == NULL)
117			error("malloc(%d) for %s: %s", (u_int)buf.st_size + 1,
118				fname, pcap_strerror(errno));
119		cc = (int)read(fd, cp, (u_int)buf.st_size);
120		if (cc < 0)
121			error("read %s: %s", fname, pcap_strerror(errno));
122		if (cc != buf.st_size)
123			error("short read %s (%d != %d)", fname, cc, (int)buf.st_size);
124	
125		close(fd);
126		/* replace "# comment" with spaces */
127		for (i = 0; i < cc; i++) {
128			if (cp[i] == '#')
129				while (i < cc && cp[i] != '\n')
130					cp[i++] = ' ';
131		}
132		cp[cc] = '\0';
133		return (cp);
134	}
