281					break;
282	
283				case 1:
284					netmask = addr;
285					break;
286				}
287				break;
288			}
289	
290			case 's': {
291				char *end;
292				long long_snaplen;
293	
294				long_snaplen = strtol(optarg, &end, 0);
295				if (optarg == end || *end != '\0'
296				    || long_snaplen < 0
297				    || long_snaplen > MAXIMUM_SNAPLEN)
298					error("invalid snaplen %s", optarg);
299				else {
