310				/* NOTREACHED */
311			}
312		}
313	
314		if (optind >= argc) {
315			usage();
316			/* NOTREACHED */
317		}
318	
319		dlt = pcap_datalink_name_to_val(argv[optind]);
320		if (dlt < 0) {
321			dlt = (int)strtol(argv[optind], &p, 10);
322			if (p == argv[optind] || *p != '\0')
323				error("invalid data link type %s", argv[optind]);
324		}
325	
326		if (infile)
327			cmdbuf = read_infile(infile);
328		else
329			cmdbuf = copy_argv(&argv[optind+1]);
330	
331	#ifdef BDEBUG
332		pcap_set_optimizer_debug(dflag);
333		pcap_set_print_dot_graph(gflag);
334	#endif
335	
336		pd = pcap_open_dead(dlt, snaplen);
337		if (pd == NULL)
338			error("Can't open fake pcap_t");
339	
340		if (pcap_compile(pd, &fcode, cmdbuf, Oflag, netmask) < 0)
341			error("%s", pcap_geterr(pd));
