345			warn("Filter doesn't pass validation");
346	
347	#ifdef BDEBUG
348		if (cmdbuf != NULL) {
349			// replace line feed with space
350			for (cp = cmdbuf; *cp != '\0'; ++cp) {
351				if (*cp == '\r' || *cp == '\n') {
352					*cp = ' ';
353				}
354			}
355			// only show machine code if BDEBUG defined, since dflag > 3
356			printf("machine codes for filter: %s\n", cmdbuf);
357		} else
358			printf("machine codes for empty filter:\n");
359	#endif
360	
361		bpf_dump(&fcode, dflag);
362		free(cmdbuf);
363		if (have_fcode)
364			pcap_freecode (&fcode);
365		pcap_close(pd);
366		exit(0);
367	}
