371	{
372		(void)fprintf(stderr, "%s, with %s\n", program_name,
373		    pcap_lib_version());
374		(void)fprintf(stderr,
375	#ifdef BDEBUG
376		    "Usage: %s [-dgO] [ -F file ] [ -m netmask] [ -s snaplen ] dlt [ expression ]\n",
377	#else
378		    "Usage: %s [-dO] [ -F file ] [ -m netmask] [ -s snaplen ] dlt [ expression ]\n",
379	#endif
380		    program_name);
381		exit(1);
382	}
